import torch
import triton
import triton.language as tl


@triton.jit
def _frac_kernel(ptr, numel, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    num_programs = tl.num_programs(0)
    stride = num_programs * BLOCK
    base = pid * BLOCK
    for start in range(base, numel, stride):
        offs = start + tl.arange(0, BLOCK)
        mask = offs < numel
        x = tl.load(ptr + offs, mask=mask)
        # trunc toward zero: floor for non-negative, ceil for negative
        t = tl.where(x >= 0, tl.floor(x), tl.ceil(x))
        frac = x - t
        tl.store(ptr + offs, frac, mask=mask)


def _num_vectorcore():
    try:
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(torch.npu.current_device())
        n = props.get("num_vectorcore", None)
        if n is None:
            n = props.get("num_aicore", None)
        if n is not None and int(n) > 0:
            return int(n)
    except Exception:
        pass
    return 20


def frac_(A):
    # frac_ is in-place: mutate A's storage and return the same tensor.
    x = A.view(-1)
    numel = x.numel()
    if numel == 0:
        return A
    # Size the block by element size so each program moves a constant byte
    # footprint; half-precision workloads were transaction/instruction limited.
    itemsize = x.element_size()
    BLOCK = 4096 * (4 // itemsize) if itemsize in (1, 2, 4) else 4096
    num_blocks = triton.cdiv(numel, BLOCK)
    grid = (min(48 * _num_vectorcore(), num_blocks),)
    _frac_kernel[grid](x, numel, BLOCK=BLOCK)
    return A
